/* @author MILO-GAO(高振銘)@2020 */ package page2020.view.bs4;import page2020.view.bs4.B4box.Size;public class B4border {	public static final String border = "border";	public static final String round = "rounded";	public static final String shadow = "shadow";	public static final class BorderColor {		public static final String primary = "border-primary";		public static final String secondary = "border-secondary";		public static final String success = "border-success";		public static final String warning = "border-warning";		public static final String danger = "border-danger";		public static final String info = "border-info";		public static final String dark = "border-dark";		public static final String light = "border-light";		public static final String white = "border-white";	}	public static final class Round {		public static final String sm = "rounded-sm";		public static final String lg = "rounded-lg";		public static final String top = "rounded-top";		public static final String right = "rounded-right";		public static final String bottom = "rounded-bottom";		public static final String left = "rounded-left";		public static final String circle = "rounded-circle";		public static final String none = "rounded-0";	}	public static final class Shadow {		public static final String sm = "shadow-sm";		public static final String lg = "shadow-lg";		public static final String none = "shadow-none";			}	public static String none() {		return border + "-0"; 	}		public static String none(String side) {		return String.format("%s-%s-0", border, side);	}	public static String round(String side) {		return String.format("%s-%s", round, side);	}	public static String roundSize(String size) {		return String.format("%s-%s", round, size);	}	public static String shadow(String size) {		String value = size.equals(Size.none) ? "-none" : size;		return String.format("%s-%s", shadow, value);	}}